<div class="page-title"><div><em>ACTIVITY</em><h1><?=tl('tx_title')?></h1><p><?=tl('tx_sub')?></p></div><a class="outline" href="<?=site_url('transactions/statement?'.http_build_query($filters))?>">↓ <?=tl('download_statement')?></a></div><section class="panel"><form class="filter" method="get"><input name="q" value="<?=html_escape($filters['search'])?>" placeholder="⌕ Search transactions"><select name="type"><option value=""><?=tl('all_types')?></option><option value="credit" <?=$filters['type']==='credit'?'selected':''?>><?=tl('credits')?></option><option value="debit" <?=$filters['type']==='debit'?'selected':''?>><?=tl('debits')?></option></select><button class="outline"><?=tl('filter')?></button></form><div class="data-table transaction-table"><div class="tr th"><span><?=tl('col_transaction')?></span><span><?=tl('col_date')?></span><span><?=tl('col_account')?></span><span><?=tl('col_amount')?></span><span><?=tl('col_status')?></span></div><?php foreach($transactions as $t):?><div class="tr"><span class="name"><i><?=transaction_icon($t['type'])?></i><b><?=html_escape($t['description'])?><small><?=html_escape($t['category'])?></small></b></span><span><?=date('M j, Y',strtotime($t['transaction_date']))?></span><span><?=html_escape($t['account_name'])?> •<?=substr($t['account_number'],-4)?></span><strong class="<?=$t['type']?>"><?=$t['type']==='credit'?'+':'−'?> <?=money($t['amount'],$t['currency'])?></strong><span class="<?=status_class($t['status'])?>"><?=ucfirst($t['status'])?></span></div><?php endforeach?></div></section>
